import 'package:flutter/widgets.dart';

import 'ambient_catalog.g.dart';
import 'sound_catalog.dart';

export 'ambient_catalog.g.dart' show kAmbientCatalog, kAmbientCategories;

/// Ambient categories use the shared [SoundCategory].
typedef AmbientCategory = SoundCategory;

/// One selectable ambient bed. The catalog itself (54 beds) is generated by
/// `tool/generate_ambient.py` into `ambient_catalog.g.dart`, so the app and
/// the audio generator can never drift apart.
@immutable
class AmbientTrack implements SoundItem {
  /// Stable id, persisted in settings and used for the asset file name.
  @override
  final String name;
  @override
  final String label;

  /// [AmbientCategory.id] this bed belongs to.
  @override
  final String category;
  @override
  final IconData icon;

  @override
  final String? pack;

  const AmbientTrack(
    this.name,
    this.label,
    this.category,
    this.icon, {
    this.pack,
  });

  @override
  String get fileName => 'ambient_$name.ogg';

  /// Flutter asset path — only valid for bundled beds (`pack == null`).
  String get asset => 'assets/sounds/$fileName';

  AmbientCategory get categoryInfo =>
      kAmbientCategories.firstWhere((c) => c.id == category);

  // Beds referenced directly from code (defaults, migration, tests).
  static const AmbientTrack rain = ambientRain;
  static const AmbientTrack ocean = ambientOcean;
  static const AmbientTrack stream = ambientStream;
  static const AmbientTrack fireplace = ambientFireplace;

  static List<AmbientTrack> get values => kAmbientCatalog;

  static AmbientTrack? byName(String? name) {
    for (final t in kAmbientCatalog) {
      if (t.name == name) return t;
    }
    return null;
  }

  @override
  bool operator ==(Object other) => other is AmbientTrack && other.name == name;

  @override
  int get hashCode => name.hashCode;

  @override
  String toString() => 'AmbientTrack($name)';
}
